package br.com.admeclesial.domain.financeiro;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="conta_financeira",schema="adm_eclesial") public class ContaFinanceira { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="organizacao_eclesial_id",nullable=false) Long organizacaoEclesialId; @Column(nullable=false,length=150) String nome; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) TipoContaFinanceira tipo; @Column(length=100) String banco; @Column(length=30) String agencia; @Column(length=50) String numero; @Column(nullable=false) boolean ativo; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;} public UUID getUuid(){return uuid;} public Long getOrganizacaoEclesialId(){return organizacaoEclesialId;} public String getNome(){return nome;} public TipoContaFinanceira getTipo(){return tipo;} public String getBanco(){return banco;} public String getAgencia(){return agencia;} public String getNumero(){return numero;} public boolean getAtivo(){return ativo;} public void setOrganizacaoEclesialId(Long v){organizacaoEclesialId=v;} public void setNome(String v){nome=v;} public void setTipo(TipoContaFinanceira v){tipo=v;} public void setBanco(String v){banco=v;} public void setAgencia(String v){agencia=v;} public void setNumero(String v){numero=v;} public void setAtivo(boolean v){ativo=v;} }